              rr(ctx, x, y, bw, bh, 7); ctx.fillStyle = C.bg; ctx.fill(); tint(ctx, C.lin, 0.1);
              ctx.lineWidth = 1.5; ctx.strokeStyle = C.lin; ctx.stroke();
