                rr(ctx, bx, yy - 8, bwid, 16, 5); ctx.fillStyle = C.sunk; ctx.fill(); ctx.lineWidth = 1; ctx.strokeStyle = C.line2; ctx.stroke();
                rr(ctx, bx, yy - 8, Math.max(8, bwid * r[1] / 100), 16, 5); tint(ctx, C.ref, 0.55);
                T(ctx, C, (j === 0 ? "≈ " : "") + nf(r[1], 0) + " %", bx + bwid + 8, yy, C.ref, { size: narrow ? 11 : 12.5, wt: 700 });
