  /* ====================================================================
     ppo11-tract — ทางเดินสัญญาณบนผังบล็อก
     ==================================================================== */
  const WORD = 24, NPRD = 2;
  const NAME = { UVM: "УВМ", CTI: "ЦТИ", M: "МПУ", U: "УПВДС", ACPU: "АЦПУ", KVK: "КВК", BOI: "БОИ", USPS: "УСПС", KU: "КУ", OK: "ОК" };

  function trLay(W, H) {
    const top = 52, bot = H - 8;
    const uw = W - 12;
    const f = [0.15, 0.07, 0.15, 0.09, 0.15, 0.06, 0.07, 0.08, 0.18];
    const X = []; let xx = 6;
    f.forEach(v => { X.push([xx, uw * v]); xx += uw * v; });
    const rh = Math.min(66, (bot - top - 24) / 4);
    const rg = (bot - top - 4 * rh) / 3;
    const rt0 = r => top + r * (rh + rg), yc = r => rt0(r) + rh / 2;
    const blk = (c, r0, r1) => ({ x: c[0], w: c[1], y: rt0(r0), h: rt0(r1) + rh - rt0(r0) });
    const B = {
      UVM: blk(X[0], 0, 2), CTI: blk(X[0], 3, 3), M: blk(X[2], 0, 0), U: blk(X[2], 1, 1), ACPU: blk(X[2], 3, 3),
      KVK: blk(X[4], 0, 0), BOI: blk(X[4], 1, 1), USPS: blk(X[4], 2, 2), KU: blk(X[6], 0, 2), OK: blk(X[8], 0, 3)
    };
    return { B, rt: rt0, yc, rh, rg, top, busX: X[3][0] + X[3][1] / 2 };
  }

  function trPaths(L) {
    const B = L.B, yc = L.yc, bx = L.busX;
    const R = b => b.x + b.w, Lf = b => b.x, cx = b => b.x + b.w / 2;
    const y0 = yc(0), y1 = yc(1), y2 = yc(2);
    const a0 = y0 - 6, b0 = y0 + 6, a1 = y1 - 6, b1 = y1 + 6, s2 = y2 - 6, acpuY = y2 + 10;
    const toAcpu = [[R(B.UVM), acpuY], [cx(B.ACPU), acpuY], [cx(B.ACPU), B.ACPU.y]];
    /* ภายใน ОК : เซนเซอร์ + ตัวส่ง ПРД */
    const r3 = L.rt(3), O = B.OK;
    const prdW = (O.w - 8 - 4 * (NPRD - 1)) / NPRD, prdY = r3 + 20, prdH = 16;
    const collY = Math.min(r3 + 42, O.y + O.h - 5);
    const prd = [];
    for (let i = 0; i < NPRD; i++) prd.push({ x: O.x + 4 + i * (prdW + 4), y: prdY, w: prdW, h: prdH });
    const last = prd[NPRD - 1];
    const hopSens = { ps: prd.map(p => [[p.x + p.w / 2, r3 + 12], [p.x + p.w / 2, prdY]]), all: true };
    const hopPrd = { ps: [[[last.x + last.w / 2, prdY + prdH], [last.x + last.w / 2, collY], [cx(B.USPS), collY], [cx(B.USPS), B.USPS.y + B.USPS.h]]] };
    for (let i = 0; i < NPRD - 1; i++) hopPrd.ps.push([[prd[i].x + prd[i].w / 2, prdY + prdH], [prd[i].x + prd[i].w / 2, collY]]);
    return {
      prd, r3,
      list: [
        { c: "lin", name: "คำสั่งออก", chain: "УВМ → МПУ → КВК → КУ → ОК",
          blocks: ["UVM", "M", "KVK", "KU", "OK"], sub: { UVM: ["(код)"], M: ["ЦАП", "→แอนะล็อก"] },
          hops: [
            { ps: [[[R(B.UVM), a0], [Lf(B.M), a0]]] },
            { ps: [[[R(B.M), a0], [bx, a0], [Lf(B.KVK), a0]]] },
            { ps: [[[R(B.KVK), a0], [Lf(B.KU), a0]]] },
            { ps: [[[R(B.KU), a0], [Lf(B.OK), a0]]] }] },
        { c: "meas", name: "ค่าตอบกลับ", chain: "ОК → КУ → КВК → МПУ → УВМ → АЦПУ",
          blocks: ["OK", "KU", "KVK", "M", "UVM", "ACPU"], sub: { M: ["АЦП", "→รหัส"] },
          hops: [
            { ps: [[[Lf(B.OK), b0], [R(B.KU), b0]]] },
            { ps: [[[Lf(B.KU), b0], [R(B.KVK), b0]]] },
            { ps: [[[Lf(B.KVK), b0], [bx, b0], [R(B.M), b0]]] },
            { ps: [[[Lf(B.M), b0], [R(B.UVM), b0]]] },
            { ps: [toAcpu] }] },
        { c: "ref", name: "โปรแกรม БЦВМ ขาออก", chain: "УВМ → УПВДС → БОИ → ОК",
          blocks: ["UVM", "U", "BOI", "OK"], sub: { U: ["ตัวสลับ", "ขาออก"], BOI: ["ขนาน→", "อนุกรม"] },
          hops: [
            { ps: [[[R(B.UVM), a1], [Lf(B.U), a1]]] },
            { ps: [[[R(B.U), a1], [bx, a1], [Lf(B.BOI), a1]]] },
            { ps: [[[R(B.BOI), a1], [Lf(B.OK), a1]]] }] },
        { c: "deep", name: "โปรแกรม БЦВМ ขากลับ", chain: "ОК → БОИ → УПВДС → УВМ",
          blocks: ["OK", "BOI", "U", "UVM"], sub: { BOI: ["อนุกรม→", "ขนาน"], U: ["ตัวสลับ", "ขาเข้า"] },
          hops: [
            { ps: [[[Lf(B.OK), b1], [R(B.BOI), b1]]] },
            { ps: [[[Lf(B.BOI), b1], [bx, b1], [R(B.U), b1]]] },
            { ps: [[[Lf(B.U), b1], [R(B.UVM), b1]]] }] },
        { c: "new", name: "สถานะหน้าสัมผัส", chain: "เซนเซอร์ → ПРД×" + NPRD + " → УСПС → УВМ · ЦТИ · АЦПУ",
          blocks: ["OK", "USPS", "UVM", "CTI", "ACPU"], sub: { USPS: ["หน้ากาก"], UVM: [WORD + " บิต"] },
          hops: [
            hopSens, hopPrd,
            { ps: [[[Lf(B.USPS), s2], [bx, s2], [R(B.UVM), s2]]] },
            { ps: [[[cx(B.UVM), B.UVM.y + B.UVM.h], [cx(B.UVM), B.CTI.y]], toAcpu], all: true }] }
      ]
    };
  }

