  const TU = 1;                         // หน่วยเวลาต่อหนึ่งงาน (สมมติ)
  const tSeq = n => n * TU;             // ต่อคิวผ่านเครื่องเดียว
  const tPar = () => TU;                // ขนาน ไม่รอกัน → เท่างานที่ยาวสุด
  const JL = ["สวิตช์สถานะ", "ประมวลผล ТМИ", "สองสถานะ", "แอนะล็อก", "ชุดข้อมูล ТМИ", "ตรวจวงจร"];

