  /* =====================================================================
     2) ppo21-find — ค้นคู่ที่ลัดด้วยรหัสผล (сл. 23–28) · 7 ขั้น
     ===================================================================== */
  const N8 = 8, K3 = 3, SHORT = [3, 5];
  const bitOf = (v, b) => (v >> b) & 1;
  const PAIRS = [];
  for (let i = 0; i < N8; i++) for (let j = i + 1; j < N8; j++) PAIRS.push([i, j]);
  const stageOf = (i, j) => K3 - 1 - (31 - Math.clz32(i ^ j));        /* ตรวจครั้งที่ (0…2) ที่คู่นี้ถูกแยกเป็นครั้งแรก */
  const NEWC = [0, 0, 0]; PAIRS.forEach(p => { NEWC[stageOf(p[0], p[1])]++; });
  const DD = [0, 1, 2].map(s => bitOf(SHORT[0] ^ SHORT[1], K3 - 1 - s));   /* d₁ d₂ d₃ */
  const DR = DD[0] * 4 + DD[1] * 2 + DD[2];
  const DR_B = DD.join("");
  const MSET = PAIRS.filter(p => (p[0] ^ p[1]) === DR);
  const MSHORT = MSET.findIndex(p => p[0] === SHORT[0] && p[1] === SHORT[1]);
  const SUMNEW = NEWC[0] + NEWC[1] + NEWC[2];
  const grp = (s, v) => { const o = []; for (let k = 0; k < N8; k++) if (bitOf(k, K3 - 1 - s) === v) o.push(k); return o; };
  const setTxt = a => "{" + a.join(",") + "}";
  const bin3 = k => k.toString(2).padStart(3, "0");
  const CNT_ALL = PAIRS.length, CNT_CODE = K3 + MSHORT + 1;      /* ไล่ถึงคู่ที่พบ */
  const CNT_WORST = K3 + MSET.length;                            /* กรณีแย่สุด */
