          T(ctx, C, reveal ? R1T + " кОм" : "?", xR + 12, m1 + 8, reveal ? C.ref : C.ink3, { size: narrow ? 10.5 : 11.5, wt: 700, mono: true, maxW: lblW, min: 7.5 });
          T(ctx, C, "R₂", xR + 12, m2 - 8, C.ref, { size: narrow ? 11.5 : 13, wt: 700 });
          T(ctx, C, reveal ? R2T + " кОм" : "?", xR + 12, m2 + 8, reveal ? C.ref : C.ink3, { size: narrow ? 10.5 : 11.5, wt: 700, mono: true, maxW: lblW, min: 7.5 });
          /* ตัวต้านทานอ้างอิง (ต่อเฉพาะขั้น 3 และ 4) */
