              T(ctx, C, r.k, ix + 10, y + (rh - 5) / 2 - 0.5, r.c, { size: narrow ? 14 : 16, wt: 700 });
              T(ctx, C, r.v, ix + (narrow ? 44 : 52), y + 12, C.ink, { size: narrow ? 12.5 : 14.5, wt: 700, mono: true, maxW: iw - 60, min: 8 });
              T(ctx, C, r.s, ix + (narrow ? 44 : 52), y + (rh - 5) - 8, C.ink2, { size: narrow ? 9.5 : 10.5, wt: 500, maxW: iw - 56, min: 7 });
