            T(ctx, C, "คลาด R₁ = R_ш/R₂ = " + nf(RSH / R2T * 100, 1) + " % · คลาด R₂ = R_ш/R₁ = " + nf(RSH / R1T * 100, 2) + " %", ix, yy, C.ink3, { size: narrow ? 9.5 : 10.5, wt: 600, maxW: iw, min: 7 });
            ctx.restore();
