  /* วางป้ายหลักการเป็นแถวไหลในกรอบกลุ่ม */
  function flow(ctx, C, items, x0, y0, cw, ch, gx, gy, fs) {
    const out = []; let x = x0, y = y0;
    items.forEach(it => {
      if (it.sub) {
        if (x > x0) { x = x0; y += ch + gy; }
        out.push({ sub: true, t: it.t, x: x0, y: y });
        y += 16; x = x0;
        return;
      }
      const th = TH[it.t] || "";
      const mw = s => { ctx.font = "600 " + s + "px " + C.font; const a = ctx.measureText(th).width; ctx.font = "500 " + (s * 0.85) + "px " + C.font; return Math.max(a, ctx.measureText(it.t).width) + 14; };
      let size = fs, w = mw(size);
      while (w > cw && size > 8) { size -= 0.5; w = mw(size); }
      w = Math.min(w, cw);
      if (x > x0 && x + w > x0 + cw) { x = x0; y += ch + gy; }
      out.push({ t: it.t, hot: it.hot, x: x, y: y, w: w, size: size });
      x += w + gx;
    });
    return { list: out, bottom: y + ch };
  }

  function prinLayout(ctx, C, W) {
    const narrow = W < 520;
    const m = 8, ch = narrow ? 34 : 38, gx = 5, gy = 5, fs = narrow ? 10.5 : 12;
    const rh = narrow ? 56 : 50;
    const x0 = m + 8, cw = W - 2 * m - 16;
    let y = m + rh + 8;
    const gs = [];
    GROUPS.forEach(g => {
      const top = y;
      const fl = flow(ctx, C, g.items, x0, top + (narrow ? 46 : 44), cw, ch, gx, gy, fs);
      const bottom = fl.bottom + 8;
      gs.push({ top: top, bottom: bottom, fl: fl });
      y = bottom + 6;
    });
    return { narrow: narrow, m: m, ch: ch, rh: rh, x0: x0, cw: cw, fs: fs, gs: gs, total: y + 2 };
  }

