              T(ctx, C, " = N·t", fx + w, fy, C.ink, { size: 13, wt: 700, mono: true });
              ctx.font = "700 13px " + C.mono; const w2 = ctx.measureText(" = N·t").width;
              ctx.font = "600 9.5px " + C.font; ctx.fillText("обр", fx + w + w2 + 1, fy + 3.6);
              T(ctx, C, "= " + N + "·" + nf(T_OBR, 0) + " = " + nf(T_CYC, 0) + " мс", fx, fy + 20, C.lin, { size: narrow ? 13 : 14, wt: 700, mono: true, maxW: W - fx - 8, min: 9 });
              ctx.restore();
