              T(ctx, C, "УСО (อุปกรณ์เชื่อมต่อกับวัตถุ)", cxm, yUSO + (ctrlH - 2) / 2, C.ink, { size: narrow ? 10.5 : 11.5, wt: 700, align: "center", maxW: W - 2 * padX - 16, min: 8.5 });
              if (stp >= 2) xbadge(ctx, C, W - padX - 12, yUSO + 1, stp === 2 ? fd(2) : 1);
