            const msgA = stp === 1 ? 1 : (stp === 2 ? fd(2) : xUvm);
            const msg = stp === 1 ? "УВМ เครื่องเดียวทำทุกวงรอบตามลำดับ" : (stp === 2 ? "ทั้ง " + N + " วงรอบหยุด" : "ระดับบนเสีย — วงรอบล่างเดินต่อ");
