    const mk = s => { ctx.font = (o.wt || 600) + " " + s + "px " + (o.mono ? C.mono : C.font); };
    mk(sz);
    if (o.maxW) while (sz > (o.min || 8.5) && ctx.measureText(txt).width > o.maxW) { sz -= 0.5; mk(sz); }
    const tw = ctx.measureText(txt).width, al = o.align || "left";
    if (!o.noclamp) {
      let left = al === "left" ? x : al === "right" ? x - tw : x - tw / 2;
      left = Math.max(4, Math.min(curW - 4 - tw, left));
      x = al === "left" ? left : al === "right" ? left + tw : left + tw / 2;
    }
    ctx.textAlign = al; ctx.textBaseline = o.base || "middle";
    if (o.halo !== 0) { ctx.lineJoin = "round"; ctx.lineWidth = o.halo || 4; ctx.strokeStyle = C.bg; ctx.strokeText(txt, x, y); }
    ctx.fillStyle = col; ctx.fillText(txt, x, y);
