          const cw = clamp(Math.floor((W - labW - 20) / NC), 20, 46);
          const x0 = labW + Math.round((W - labW - NC * cw) / 2);
          const top = 32, rowsN = 11, rowH = (H - top - 50) / rowsN, chh = Math.max(16, rowH - 4);
          const ry = r => top + r * rowH;
